def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return '错误：除数不能为零'
    except TypeError:
        return '错误：参数必须是数字'

print(safe_divide(10, 2))
print(safe_divide(10, 0))
print(safe_divide('10', 2))

